            TodoFilter::InProgress => status == "in_progress",
            TodoFilter::Backlog => status == "backlog",
            TodoFilter::Draft => status == "draft",
            TodoFilter::Completed => status == "completed",
            TodoFilter::NotDone => status == "not_done",
